def count_common(words):
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
    most_common = []
    max_count = 0
    for word, count in word_count.items():
        if count > max_count:
            max_count = count
            most_common = [(word, count)]
        elif count == max_count:
            most_common.append((word, count))
    return most_common
```

