def find_Min(arr, start, end):
    if start == end:
        return arr[start]
    if start > end:
        return -1
    mid = (start + end) // 2
    if arr[mid] > arr[mid + 1]:
        return arr[mid + 1]
    if arr[mid - 1] > arr[mid]:
        return arr[mid]
    if arr[start] > arr[mid]:
        return find_Min(arr, start, mid - 1)
    return find_Min(arr, mid + 1, end)
```

