def count_binary_seq(n):
    if n == 0:
        return 1.0
    if n == 1:
        return 2.0
    count = 0
    for i in range(2**n):
        binary = bin(i)[2:].zfill(n)
        if sum(int(bit) for bit in binary[:n]) == sum(int(bit) for bit in binary[n:]):
            count += 1
    return count / 2**n
```

