def permute_string(s):
    def permute(s, l, r):
        if l == r:
            yield s
        else:
            for i in range(l, r + 1):
                s[l], s[i] = s[i], s[l]
                yield from permute(s, l + 1, r)
                s[l], s[i] = s[i], s[l]
    return list(permute(list(s), 0, len(s) - 1))
