            max_gold = max(max_gold, max_gold(grid, i, j))
    return max_gold

def max_gold(grid, i, j):
    if i < 0 or j < 0 or i >= len(grid) or j >= len(grid[0]):
        return -float('inf')
    if grid[i][j] == 0:
        return 0
    grid[i][j] = 0
    up = max_gold(grid, i-1, j)
    down = max_gold(grid, i+1, j)
    left = max_gold(grid, i, j-1)
    right = max_gold(grid, i, j+1)
    return grid[i][j] + max(up, down, left, right)
```

